export const PLACEHOLDER_COLLEGE_VALUES = new Set([
  "",
  "unspecified",
  "independent",
  "unspecified / independent",
  "unspecified/independent",
  "profile form yet to fill",
  "not specified",
  "na",
  "n/a",
  "none",
  "null",
  "—",
  "-"
]);

export function isPlaceholderCollege(collegeName?: string | null): boolean {
  if (!collegeName) return true;
  return PLACEHOLDER_COLLEGE_VALUES.has(collegeName.trim().toLowerCase());
}

/**
 * Resolves the institutional college name for a student record according to the required rules:
 * 1. If valid college name is in graduationCollegeName, preserve and return it directly.
 * 2. If graduationCollegeName is empty or "Unspecified" / "Independent", check postGraduationCollegeName.
 * 3. Verify whether the student has a matching college entry in Placement_Pool_Google_AI_Studio
 *    (checked against student ID, user ID, email, mobile number, or full name).
 * 4. If a valid college is found in Placement_Pool_Google_AI_Studio, display that actual college name.
 * 5. If no valid college information is available / not found in Placement_Pool_Google_AI_Studio,
 *    display "Profile Form Yet to Fill".
 */
export function resolveStudentCollege(s: Student): string {
  // 1. Preserve valid Graduation College if present in student record
  const grad = (s.graduationCollegeName || "").trim();
  if (!isPlaceholderCollege(grad)) {
    return grad;
  }

  // 2. Check if student record has valid Post-Graduation College
  const postGrad = (s.postGraduationCollegeName || "").trim();
  if (!isPlaceholderCollege(postGrad)) {
    return postGrad;
  }

  // 3. Verify against Placement_Pool_Google_AI_Studio data source using student identifiers
  const sId = (s.studentId || "").trim().toUpperCase();
  const uId = (s.userId || "").trim().toUpperCase();
  const email = (s.personalMailId || "").trim().toLowerCase();
  const mobile = (s.mobileNumber || "").replace(/\D/g, "").slice(-10);
  const name = (s.fullName || "").trim().toLowerCase();

  const matchedCollege = 
    (sId && PLACEMENT_POOL_COLLEGES[sId]) ||
    (uId && PLACEMENT_POOL_COLLEGES[uId]) ||
    (email && PLACEMENT_POOL_COLLEGES[email]) ||
    (mobile && PLACEMENT_POOL_COLLEGES[mobile]) ||
    (name && PLACEMENT_POOL_COLLEGES[name]);

  if (matchedCollege && !isPlaceholderCollege(matchedCollege)) {
    return matchedCollege;
  }

  // 4. College not found in Placement_Pool_Google_AI_Studio & no valid college info -> "Profile Form Yet to Fill"
  return "Profile Form Yet to Fill";
}
